//! Retain bounded private-call context while erasing repeated jump-source cycles.
//!
//! Transfer has already applied the declared context_depth bound. Canonicalizing
//! its history never increases that length, and a repeated loop source settles
//! on its second traversal instead of creating one key per retained iteration.

use super::{BTreeMap, BTreeSet, MachineError};
use std::sync::OnceLock;

#[cfg(test)]
mod tests;

// Prototype-only selection for two separate process runs. Neither this switch
// nor the rejected strategy will be copied into the final implementation.
pub(super) fn canonical(history: &[usize]) -> Result<Vec<usize>, MachineError> {
    static RECENT: OnceLock<bool> = OnceLock::new();
    if *RECENT.get_or_init(|| {
        std::env::var_os("EVM_PROCEDURE_CONTEXT_PROTOTYPE").is_some_and(|style| style == "mru")
    }) {
        recent_sources(history)
    } else {
        erase_cycles(history)
    }
}

pub(super) fn work_size(length: usize) -> usize {
    let levels = usize::try_from(length.max(1).ilog2())
        .unwrap_or(usize::MAX)
        .saturating_add(1);
    // Charge retained items and tree levels conservatively; these are logical
    // work units, not a measurement of machine comparison or elapsed time.
    length.saturating_mul(levels).saturating_mul(8)
}

pub(super) fn erase_cycles(history: &[usize]) -> Result<Vec<usize>, MachineError> {
    let mut output = Vec::new();
    let mut positions = BTreeMap::new();
    for source in history {
        MachineError::check_cancelled()?;
        if let Some(position) = positions.get(source).copied() {
            for removed in output.drain(position + 1..) {
                positions.remove(&removed);
            }
        } else {
            positions.insert(*source, output.len());
            output.push(*source);
        }
    }
    Ok(output)
}

pub(super) fn recent_sources(history: &[usize]) -> Result<Vec<usize>, MachineError> {
    let mut seen = BTreeSet::new();
    let mut output = Vec::new();
    for source in history.iter().rev() {
        MachineError::check_cancelled()?;
        if seen.insert(*source) {
            output.push(*source);
        }
    }
    output.reverse();
    Ok(output)
}

//! Context partitioning retains finite callers without loop warmup.

use super::{canonical, erase_cycles, recent_sources, work_size};
use crate::{
    analysis::{machine::fixtures::fixture, transfer},
    domain::Domain,
};
use std::collections::BTreeSet;

#[test]
fn sequential_helper_calls_keep_the_latest_actual_callsite() {
    assert_eq!(erase_cycles(&[18]).unwrap(), [18]);
    assert_eq!(erase_cycles(&[18, 320, 256]).unwrap(), [18, 320, 256]);
    assert_eq!(
        erase_cycles(&[18, 320, 256, 320, 272]).unwrap(),
        [18, 320, 272]
    );
    assert_eq!(
        erase_cycles(&[18, 320, 256, 320, 272, 320, 288]).unwrap(),
        [18, 320, 288]
    );
}

#[test]
fn nested_helpers_retain_the_outer_callsite_prefix() {
    assert_eq!(
        erase_cycles(&[10, 100, 200, 210, 200, 220, 100, 120, 200]).unwrap(),
        [10, 100, 120, 200]
    );
    assert_ne!(
        erase_cycles(&[10, 100, 110, 200]).unwrap(),
        erase_cycles(&[10, 100, 120, 200]).unwrap()
    );
}

#[test]
fn a_real_loop_has_two_contexts_instead_of_128_iteration_keys() {
    let mut current = Vec::new();
    let mut contexts = BTreeSet::new();
    for source in [12, 13].into_iter().cycle().take(256) {
        current.push(source);
        current = erase_cycles(&current).unwrap();
        contexts.insert(current.clone());
    }
    assert_eq!(contexts, BTreeSet::from([vec![12], vec![12, 13]]));
}

#[test]
fn an_empty_declared_context_stays_empty_and_bounded_histories_never_grow() {
    assert!(erase_cycles(&[]).unwrap().is_empty());
    assert_eq!(work_size(0), 0);
    let history = (0..128).collect::<Vec<_>>();
    assert_eq!(erase_cycles(&history).unwrap(), history);
    assert!(work_size(128) >= 128);
}

#[test]
fn known_forms_keep_and_charge_context_while_unknown_forms_erase_it() {
    let domain = Domain::default();
    for known in [true, false] {
        let (world, entry) = if known {
            fixture(&[(0x101, "00")])
        } else {
            fixture(&[])
        };
        let mut payload = transfer::initial(&world, &entry, domain).unwrap();
        let baseline = super::super::form(&payload, &entry, domain).unwrap();
        payload.active_mut().key.jump_history = vec![1, 2, 3, 2];
        let formed = super::super::form(&payload, &entry, domain).unwrap();
        if known {
            let expected = canonical(&payload.active().key.jump_history).unwrap();
            assert_eq!(formed.active().key.jump_history, expected);
            assert_eq!(formed.work_size(), baseline.work_size() + expected.len());
        } else {
            assert!(formed.active().key.jump_history.is_empty());
            assert_eq!(formed.work_size(), baseline.work_size());
        }
    }
}

#[test]
fn recent_sources_keep_new_nested_callers_that_prefix_cycle_erasure_discards() {
    let first = [18, 400];
    let second = [18, 400, 448, 416, 256, 400];
    assert_eq!(
        erase_cycles(&first).unwrap(),
        erase_cycles(&second).unwrap()
    );
    assert_ne!(
        recent_sources(&first).unwrap(),
        recent_sources(&second).unwrap()
    );
    assert_eq!(recent_sources(&second).unwrap(), [18, 448, 416, 256, 400]);
    assert_eq!(recent_sources(&[1, 2, 3, 2]).unwrap(), [1, 3, 2]);
    assert!(recent_sources(&[]).unwrap().is_empty());
}

#[test]
fn recent_sources_reach_a_periodic_loop_context_after_one_traversal() {
    let mut current = Vec::new();
    let mut contexts = BTreeSet::new();
    for source in [12, 13].into_iter().cycle().take(256) {
        current.push(source);
        current = recent_sources(&current).unwrap();
        contexts.insert(current.clone());
    }
    assert_eq!(
        contexts,
        BTreeSet::from([vec![12], vec![12, 13], vec![13, 12]])
    );
}

#[test]
fn context_depth_zero_stays_empty_during_actual_loop_execution_and_summary_replay() {
    use super::super::{Counters, StorageReadPolicy, Table, WorkBudget};
    use crate::analysis::ExecutionConfig;
    let (world, entry) = fixture(&[(0x101, "5f5b60010180601190106100015750602a5f5260205ff3")]);
    let mut config = ExecutionConfig {
        max_work: 1_000_000_000,
        ..ExecutionConfig::default()
    };
    config.analysis.context_depth = 0;
    config.analysis.max_constants = 512;
    config.analysis.relations.enabled = false;
    let domain = config.domain().unwrap();
    let input = transfer::initial(&world, &entry, domain).unwrap();
    let mut table = Table::default();
    let mut counters = Counters::default();
    let mut budget = WorkBudget::new(config.max_work);
    let (execution, record) = table.execute(
        0,
        &world,
        &entry,
        input,
        &config,
        domain,
        &mut budget,
        &mut counters,
        StorageReadPolicy::Abstract,
    );
    assert!(execution.frontiers.is_empty());
    assert!(record.closed);
    assert!(
        table
            .nodes
            .iter()
            .all(|node| node.payload.active().key.jump_history.is_empty())
    );
    assert!(table.nodes.len() <= 4);
}
